-- 配送与交易配置管理入口；不修改角色授权，可重复执行。
BEGIN;
SET @trade_root=(SELECT menu_id FROM sys_menu WHERE parent_id=0 AND path='trade' AND menu_type='M' ORDER BY menu_id LIMIT 1);
SET @delivery_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@trade_root AND path='delivery-expresses' AND menu_type='C' ORDER BY menu_id LIMIT 1);
SET @delivery_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@trade_root AND path='delivery-templates' AND menu_type='C' ORDER BY menu_id LIMIT 1);
SET @delivery_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@trade_root AND path='config' AND menu_type='C' ORDER BY menu_id LIMIT 1);
COMMIT;
